67:    package static func stage<Table: CanvasValueTable>(
68:        from semantic: borrowing SemanticRecordStore<CanvasSemanticPayload<Table.CaptureStorage>>,
69:        into values: borrowing CanvasStagedValues<SemanticRecordReference, Table>,
70:        table: borrowing Table
71:    ) throws(DrawingError) {
72:        guard values.count == 0 else { throw .invariantViolation }
73:        let table = copy table
74:        do throws(SemanticExpansionError) {
75:            try semantic.takePendingCanvas { (identity, payload) throws(SemanticExpansionError) in
76:                guard case .canvas(.some(let value)) = payload else { throw .invariantViolation }
77:                do throws(DrawingError) {
78:                    try values.stage(identity: identity, value: value, table: table)
79:                } catch {
80:                    throw error == .capacityExhausted ? .capacityExhausted : .invariantViolation
81:                }
82:                payload = .canvas(nil)
83:            }
84:        } catch {
85:            values.discard()
86:            try? semantic.discardCandidate()
87:            throw error == .capacityExhausted ? .capacityExhausted : .invariantViolation
88:        }
